update(dt, player, grid) {
    if (this.dead) { this.deathT += dt; return null; }
    this.timer += dt;
    this.animT += dt;
    this.attackCooldown = max(0, this.attackCooldown - dt);

    // WHY: pain interrompe ação; ao terminar, retoma chase se ainda vê o player
    if (this.state === 'pain') return this.updatePain(dt, player, grid);

    const seen = this.canSee(grid, player);
    if (this.state === 'idle') {
      if (seen) this.setState('chase');
      return null;
    }
    if (this.state === 'chase') return this.updateChase(dt, player, grid, seen);
    if (this.state === 'windup') return this.updateWindup(dt, player, grid, seen);
    if (this.state === 'attack') return this.updateAttack(player, grid, seen);
    return null;
  }

  // WHY: pain — countdown e retomada; isolado p/ update() ficar enxuto
  updatePain(dt, player, grid) {
    this.painTimer -= dt;
    if (this.painTimer <= 0) {
      this.setState(this.canSee(grid, player) ? 'chase' : 'idle');
    }
    return null;
  }

  // WHY: chase — persegue e, no alcance com cooldown zerado, arma o telegraph
  updateChase(dt, player, grid, seen) {
    if (!seen) { this.setState('idle'); return null; }
    const d = dirTo(this.pos, player.pos);
    this.yaw = Math.atan2(d.x, d.z);
    // WHY: moveAxis usa grid {x,y} (x=col, y=row) — traduz de/para {x,z} (lição W3)
    const gp = { x: this.pos.x, y: this.pos.z };
    const v = { x: d.x * this.stats.speed, y: d.z * this.stats.speed };
    const rX = moveAxis(gp, v, 'x', dt, grid, this.stats.size * 0.45);
    const rZ = moveAxis(rX.pos, { x: rX.vel.x, y: rX.vel.y }, 'y', dt, grid, this.stats.size * 0.45);
    this.pos.x = rZ.pos.x;
    this.pos.z = rZ.pos.y;
    const dist2 = hypot(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
    if (dist2 <= this.attackRange && this.attackCooldown <= 0) {
      // WHY: telegraph — wind-up visível antes do lunge (estado novo do FSM)
      this.windupT = C.COMBAT.windupDur;
      this.windupTotal = C.COMBAT.windupDur;
      this.setState('windup');
    }
    return null;
  }

  // WHY: windup — recua visualmente (main.js), cancela se perde visão, dispara ao fim
  updateWindup(dt, player, grid, seen) {
    if (!seen) { this.setState('idle'); return null; }
    const d = dirTo(this.pos, player.pos);
    this.yaw = Math.atan2(d.x, d.z);
    this.windupT -= dt;
    if (this.windupT <= 0) this.setState('attack');
    return null;
  }

  // WHY: attack — ataque é transiente: dispara uma vez e volta a chase/idle
  updateAttack(player, grid, seen) {
    this.attackCooldown = this.attackRate();
    const evt = this.fireAt(player, grid);
    this.setState(seen ? 'chase' : 'idle');
    return evt;
  }

