// WHY: bobbing da câmera
const cameraBob = (time, moving, speed) => {
  const bobAmp = C.PHYSICS.bobAmp;
  const bobFreq = C.PHYSICS.bobFreq;
  if (!moving) return { x: 0, y: 0 };
  return {
    x: Math.sin(time * bobFreq) * bobAmp,
    y: Math.sin(time * bobFreq * 2) * bobAmp * 0.5,
  };
};

// WHY: roll lateral sincronizado com o bob — inclinação sutil dá peso ao andar
const cameraRoll = (time, moving) => {
  if (!moving) return 0;
  return Math.sin(time * C.PHYSICS.bobFreq) * C.PHYSICS.bobRoll;
};

export {
  applyGravity,
  applyFriction,
  accelerate,
  moveAxis,
  tryJump,
  knockback,
  splashDamage,
  cameraBob,
  cameraRoll,
};

