tool_input.newString:
play(name) {
    this.lastPlayed = name;
    this.queue.push(name);
    const s = SOUNDS[name];
    if (!s) return false;
    const ctx = this.ensureCtx();
    if (!ctx || this.muted) return false;
    const now = ctx.currentTime;
    // WHY: envelope de decaimento exponencial compartilhado por camada
    const gainEnv = (vol, t, d) => {
      const g = ctx.createGain();
      g.gain.setValueAtTime(vol, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + d);
      return g;
    };
    // WHY: camada principal preserva type/freq/dur/slide do contrato de SOUNDS
    const synth = (type, freq, dur, slide, vol = 0.15) => {
      const osc = ctx.createOscillator();
      const gain = gainEnv(vol, now, dur);
      osc.type = type;
      osc.frequency.setValueAtTime(freq, now);
      osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), now + dur);
      osc.connect(gain).connect(ctx.destination);
      osc.start(now);
      osc.stop(now + dur);
    };
    synth(s.type, s.freq, s.dur, s.slide);
    // WHY: camadas extras — corpo/atrito do som (tiro encorpado, porta pesada)
    for (const l of s.layers ?? []) synth(l.type, l.freq, l.dur, l.slide, l.gain ?? 0.12);
    // WHY: estalo de ruído branco (guarded p/ ctx mock de teste sem buffer)
    if (s.noise && ctx.createBufferSource && ctx.createBuffer) {
      const dur = s.noise.dur;
      const buf = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * dur), ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
      const src = ctx.createBufferSource();
      src.buffer = buf;
      src.connect(gainEnv(s.noise.gain ?? 0.2, now, dur)).connect(ctx.destination);
      src.start(now);
    }
    return true;
  }

