// WHY: tijolo 64×32 com argamassa escura, contraste forte, tijolos quebrados e
// grão denso — Duke/Quake; bump: tijolo alto, junta funda
const wallTex = () => makeTexture('wall', 128, 128, (g, w, h) => {
  g.fillStyle = '#17120d';
  g.fillRect(0, 0, w, h);
  const bw = 64, bh = 32;
  for (let y = 0; y < h; y += bh) {
    const off = (y / bh) % 2 === 0 ? 0 : bw / 2;
    for (let x = -bw / 2; x < w; x += bw) {
      const n = seededRand(x * 7 + y * 13);
      const chipped = seededRand(x * 3 + y * 29) > 0.85;
      const r = (150 + n * 44) | 0, g2 = (100 + n * 36) | 0, b = (66 + n * 26) | 0;
      // sombreamento topo→base (luz vinda de cima — forma cilíndrica do tijolo)
      const grad = g.createLinearGradient(0, y + 2, 0, y + bh - 2);
      grad.addColorStop(0, `rgb(${(r * 1.22) | 0},${(g2 * 1.18) | 0},${(b * 1.14) | 0})`);
      grad.addColorStop(0.45, `rgb(${r},${g2},${b})`);
      grad.addColorStop(1, `rgb(${(r * 0.55) | 0},${(g2 * 0.52) | 0},${(b * 0.5) | 0})`);
      g.fillStyle = grad;
      g.fillRect(x + off + 3, y + 3, bw - 6, bh - 6);
      // WHY: tijolo quebrado (canto faltando) — variedade sem assets externos
      if (chipped) { g.fillStyle = '#17120d'; g.fillRect(x + off + 3, y + 3, bw * 0.35, bh * 0.3); }
      // grão: 10 speckles claros/escuros por tijolo
      for (let i = 0; i < 10; i++) {
        const gx = x + off + 4 + seededRand(x + i * 31) * (bw - 10);
        const gy = y + 4 + seededRand(y + i * 47) * (bh - 10);
        const sp = seededRand(gx * 13 + gy * 17);
        g.fillStyle = sp > 0.5 ? `rgba(255,235,210,${0.12 + sp * 0.14})` : `rgba(0,0,0,${0.16 + sp * 0.1})`;
        g.fillRect(gx, gy, 2, 2);
      }
    }
  }
});

