const floorTex = () => makeTexture('floor', 128, 128, (g, w, h) => {
  g.fillStyle = '#2b2b34';
  g.fillRect(0, 0, w, h);
  const s = 64;
  for (let y = 0; y < h; y += s) {
    for (let x = 0; x < w; x += s) {
      const v = seededRand(x * 3 + y * 11) * 30;
      const t = 128 + v;
      const base = `rgb(${t | 0},${(t * 0.95) | 0},${(t * 1.08) | 0})`;
      g.fillStyle = base;
      g.fillRect(x + 3, y + 3, s - 6, s - 6);
      // borda interna mais clara (desgaste) + sombra na junta
      g.fillStyle = 'rgba(255,255,255,0.09)';
      g.fillRect(x + 3, y + 3, s - 6, 2);
      g.fillStyle = 'rgba(0,0,0,0.22)';
      g.fillRect(x + 3, y + s - 7, s - 6, 1);
      // grão: 14 speckles por laje (claro/escuro)
      for (let i = 0; i < 14; i++) {
        const gx = x + 5 + seededRand(x + i * 17) * (s - 12);
        const gy = y + 5 + seededRand(y + i * 23) * (s - 12);
        g.fillStyle = seededRand(x * 5 + y * 7 + i * 3) > 0.45 ? 'rgba(255,255,255,0.12)' : 'rgba(0,0,0,0.18)';
        g.fillRect(gx, gy, 3, 3);
      }
      // WHY: mancha de óleo/sujeira ocasional — quebra a repetição da laje
