        g.fill();
      }
      // rachadura ocasional
      if (seededRand(x * 29 + y * 31) > 0.7) {
        g.strokeStyle = 'rgba(0,0,0,0.3)';
        g.lineWidth = 1;
        g.beginPath();
        g.moveTo(x + 10, y + 10 + seededRand(x + y) * 20);
        g.lineTo(x + 30, y + 20 + seededRand(x * 2 + y) * 30);
        g.lineTo(x + 55, y + 15 + seededRand(x * 3 + y) * 25);
        g.stroke();
      }
    }
  }
});

