const mesh = enemyMeshes.get(e);
      if (mesh) {
        if (e.dead) {
          // WHY: morte dramática — tomba (x), gira (z) e quica no impacto do chão
          const k = Math.min(1, e.deathT / C.COMBAT.deathFall);
          const bounce = Math.sin(e.deathT * 26) * 0.05 * (1 - k);
          mesh.rotation.x = -k * 1.25;
          mesh.rotation.z = Math.sin(e.deathT * 18) * 0.3 * e.deathSpin;
          mesh.position.y = Math.max(0.04, e.stats.size * 0.8 * (1 - k * 0.72) + bounce);
          mesh.position.set(e.pos.x, mesh.position.y, e.pos.z);
          // WHY: impacto do corpo no chão — poeira na base (uma vez por queda)
          if (!e.impactDone && e.deathT >= C.COMBAT.deathFall) {
            e.impactDone = true;
            w.particles.impact(e.pos.x, e.pos.z, 0.06, 8);
          }
          if (e.deathT >= C.COMBAT.deathRemove && mesh.parent) w.engine.world.remove(mesh);
        } else {
          // WHY: yaw aponta pro player (FSM já calcula) — mesh rotaciona para "olhar"
          mesh.rotation.y = e.yaw;
          // WHY: bob de caminhada (chase) vs respiração idle — animT avança sempre
          const moving = e.state === 'chase' || e.state === 'attack' || e.state === 'windup';
          const bob = moving
            ? Math.abs(Math.sin(e.animT * 9)) * e.stats.size * 0.16
            : Math.sin(e.animT * 2) * e.stats.size * 0.05;
          mesh.position.set(e.pos.x, e.stats.size * 0.8 + bob, e.pos.z);
          // WHY: dor — flash emissive + treme; ataque — lunges na direção do player
          let flash = e.painTimer > 0 ? 1.1 : 0.28;
          // WHY: telegraph — windup recua, cresce e brilha antes do lunge (visível)
          if (e.state === 'windup' && e.windupTotal > 0) {
            const wu = Math.min(1, 1 - e.windupT / e.windupTotal);
            const d = dirTo(e.pos, w.player.pos);
            mesh.position.x -= d.x * wu * C.COMBAT.windupPull;
            mesh.position.z -= d.z * wu * C.COMBAT.windupPull;
            mesh.scale.setScalar(1 + wu * 0.1);
            flash = 0.28 + wu * 1.4;
          } else if (mesh.scale.x !== 1) {
            mesh.scale.setScalar(1);
          }
          for (const c of mesh.children) {
            if (c.material && c.material.emissiveIntensity !== undefined) c.material.emissiveIntensity = flash;
          }
          if (e.attackAnim > 0) {
            e.attackAnim -= dt;
            const d = dirTo(e.pos, w.player.pos);
            mesh.position.x += d.x * e.attackAnim * 2;
            mesh.position.z += d.z * e.attackAnim * 2;
          }
        }
      }

