tool_input.newString:
document.addEventListener('mousedown', (e) => {
    if (e.button !== 0 || w.game.state !== STATES.PLAYING) return;
    const evt = w.player.weapons.fire(w.player, w.level.grid);
    if (!evt) return;
    // WHY: kick do viewmodel por arma — fist avança (negativo), armas recuam (positivo)
    viewKick = evt.type === 'melee' ? 0.9 : 0.6;
    // WHY: som + muzzle flash + fumaça curta no cano (armas de fogo)
    if (evt.type !== 'melee') {
      w.audio.play('shoot');
      muzzleT = C.COMBAT.muzzleDur;
      muzzleLight.intensity = C.COMBAT.muzzleLight;
      const mx = w.player.pos.x + Math.sin(w.player.yaw) * 1.4;
      const mz = w.player.pos.z - Math.cos(w.player.yaw) * 1.4;
      w.particles.spark(mx, mz, 1.4, 2);
    }
    if (evt.type === 'melee') {
      const t = meleeTarget(w.player, w.enemies, evt.range);
      if (t) {
        t.damage(evt.damage);
        hitstopT = Math.max(hitstopT, C.WEAPON.fist.hitstop);
        w.audio.play('damage'); w.particles.blood(t.pos.x, t.pos.z, t.stats.size * 0.7, 6);
      }
    } else if (evt.type === 'hitscan') {
      const t = raycastEnemy(w.player, w.level.grid, w.enemies, evt.hit.dist);
      if (t) {
        t.damage(evt.damage);
        hitstopT = Math.max(hitstopT, C.WEAPON.pistol.hitstop);
        w.audio.play('damage'); w.particles.blood(t.pos.x, t.pos.z, t.stats.size * 0.7, 6);
      }
    } else if (evt.type === 'spread') {
      for (const pellet of evt.pellets) {
        const t = raycastEnemy(w.player, w.level.grid, w.enemies, pellet.dist);
        if (t) {
          t.damage(evt.damage);
          hitstopT = Math.max(hitstopT, C.WEAPON.shotgun.hitstop);
          w.audio.play('damage'); w.particles.blood(t.pos.x, t.pos.z, t.stats.size * 0.5, 4);
        }
      }
    } else if (evt.type === 'projectile') {
      const dir = { x: evt.proj.dx, z: evt.proj.dz };
      pushProjectile(w.player.pos, dir, evt.proj.speed, evt.damage, 'player', evt.splash ?? 0);
    }
  });

