it('chase -> windup -> attack dispara melee (demon, dist < 1.5) e volta a chase', () => {
    const e = mkEnemy('demon', 1.5, 2.5);
    const player = mkPlayer(2.5, 2.5);
    e.update(STEP, player, arena); // idle -> chase
    e.update(STEP, player, arena); // chase -> windup (telegraph antes do lunge)
    assert.equal(e.state, 'windup');
    let evt = null;
    for (let i = 0; i < Math.ceil(C.COMBAT.windupDur / STEP) + 2; i++) {
      const r = e.update(STEP, player, arena);
      if (r) { evt = r; break; }
    }
    assert.equal(evt.type, 'melee');
    assert.equal(evt.damage, C.ENEMY.demon.dmg);
    assert.equal(e.state, 'chase');
    // cooldown ativo impede windup/ataque imediato
    e.update(STEP, player, arena);
    assert.equal(e.state, 'chase');
  });

