    const player = mkPlayer(3.5, 2.5);
    e.update(STEP, player, arena); // idle -> chase
    e.update(STEP, player, arena); // chase -> windup
    assert.equal(e.state, 'windup');
    assert.ok(e.windupT > 0, 'windupT deve contar o telegraph');
    assert.equal(e.windupTotal, C.COMBAT.windupDur);
  });

  it('cancela windup se perde a visão do player (volta a idle)', () => {
    const e = mkEnemy('imp');
    const player = mkPlayer(3.5, 2.5);
    e.update(STEP, player, arena); // idle -> chase
    e.update(STEP, player, arena); // chase -> windup
    const r = e.update(STEP, mkPlayer(1.5, 1.5), block); // parede entre → sem LOS
    assert.equal(e.state, 'idle');
    assert.equal(r, null);
  });

  it('morte dramática: damage letal seta deathSpin e estado death', () => {
    const e = mkEnemy('imp');
    e.damage(999);
    assert.equal(e.dead, true);
    assert.ok(Math.abs(e.deathSpin) <= 1, 'deathSpin é direção normalizada');
  });
});

