    // WHY: câmera FPS — posição + bob de caminhada + yaw/pitch do input
    camera.position.set(w.player.pos.x, w.player.viewY(), w.player.pos.z);
    camera.rotation.order = 'YXZ';
    camera.rotation.y = -w.player.yaw;
