    // WHY: roll sincronizado com o bob — inclinação sutil dá peso ao andar
    camera.rotation.z = cameraRoll(w.player.bobTime, w.player.isMoving());
    // WHY: shake de tela ao tomar dano — deslocamento aleatório (decai no update)
    if (shakeT > 0) {
