import { Scene, PerspectiveCamera, WebGLRenderer, AmbientLight } from 'three';
import { Player } from './player';
import { World } from './world';
import { Physics } from './physics';
import { HUD } from './ui/hud';
import { Minimap } from './ui/minimap';

const scene = new Scene();
const camera = new PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 2000);
const renderer = new WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);
scene.add(new AmbientLight(0xffffff, 0.3));

const physics = new Physics();
const world = new World(physics, scene);
const player = new Player(camera, world, physics);
player.initControls();
const hud = new HUD();
const minimap = new Minimap(world.getMapBounds());

function animate() {
  requestAnimationFrame(animate);
  physics.step();
  world.update();
  player.update();
  hud.render(player.getStats());
  minimap.render(player.getPos());
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  renderer.setSize(window.innerWidth, window.innerHeight);
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
});
