  // (viewmodel + meshes W9) faz o loop acumular catch-up, updates/s pode passar de 66
  expect(perf.updates / perf.dt).toBeGreaterThan(55);
  expect(perf.updates / perf.dt).toBeLessThan(90);
  console.log(`perf: updates/s=${(perf.updates / perf.dt).toFixed(1)} renderFps=${perf.renderFps.toFixed(1)}`);

