// WHY: 3 amostras de 1s, exigimos a MELHOR — o acumulador fixed-step deve
  // sustentar >=55 updates/s em estado estável; um spike transitório de carga
  // (máquina com 7 LLMs locais em paralelo) não pode pifar o teste inteiro.
  const perf = await page.evaluate(async () => {
    const w = window.__doom;
    const sample = async () => {
      const u0 = w.__updates ?? 0;
      let frames = 0;
      const t0 = performance.now();
      await new Promise((resolve) => {
        const tick = () => {
          frames++;
          if (performance.now() - t0 < 1000) requestAnimationFrame(tick);
          else resolve();
        };
        requestAnimationFrame(tick);
      });
      const dt = (performance.now() - t0) / 1000;
      return { updates: (w.__updates ?? 0) - u0, dt, renderFps: frames / dt };
    };
    const samples = [await sample(), await sample(), await sample()];
    const best = samples.reduce((a, b) => (b.updates / b.dt > a.updates / a.dt ? b : a));
    return { best, samples };
  });
  const r = perf.best.updates / perf.best.dt;
